const questions: Question[] = [
{ id:1, topic:"membrane", title:"Структура биологической мембраны, транспорт веществ и виды ионных каналов", answer:"Мембрана построена по жидкостно-мозаичной модели: фосфолипидный бислой, белки, холестерин и углеводные компоненты. Пассивный транспорт идёт без затрат АТФ (простая и облегчённая диффузия), активный — с затратой энергии и может идти против градиента. Каналы бывают потенциал-зависимыми и лиганд-зависимыми.", simple:"Мембрана — стена с воротами. Липиды образуют стену, белки — ворота и переносчики, а насосы тратят энергию, чтобы перемещать вещества против естественного направления." },
{ id:2, topic:"membrane", title:"Потенциал покоя: определение, механизмы, факторы и регистрация", answer:"Потенциал покоя (ПП) — разность потенциалов между внутренней и наружной сторонами мембраны невозбуждённой клетки; обычно около −70…−90 мВ. Он связан с высокой проницаемостью мембраны для K⁺, меньшей проницаемостью для Na⁺ и работой Na⁺/K⁺-насоса. Регистрируется внутриклеточным микроэлектродом.", simple:"Клетка как батарейка: внутри относительно снаружи отрицательный заряд. Калий выходит из клетки, а насос поддерживает разницу концентраций ионов." },
{ id:3, topic:"membrane", title:"Формирование ПП, равновесный калиевый потенциал и Na⁺/K⁺-насос", answer:"Выход K⁺ по электрохимическому градиенту делает внутреннюю сторону мембраны отрицательной. Равновесный калиевый потенциал — потенциал, при котором химическая и электрическая силы для K⁺ уравновешены. Реальный ПП зависит также от проницаемости для других ионов. Насос переносит 3 Na⁺ наружу и 2 K⁺ внутрь, поддерживая градиенты.", simple:"Калий уносит из клетки положительный заряд. Насос постоянно возвращает K⁺ и удаляет Na⁺, чтобы батарейка не разрядилась." },
{ id:4, topic:"membrane", title:"Потенциал действия (ПД): характеристика и фазы", answer:"ПД — быстрое изменение мембранного потенциала при возбуждении. В принятой в конспекте схеме выделяют медленную деполяризацию (предспайк), быструю деполяризацию, быструю реполяризацию, медленную реполяризацию и гиперполяризацию. Быстрая деполяризация связана преимущественно с входом Na⁺, реполяризация — с инактивацией Na⁺-каналов и выходом K⁺.", simple:"Сначала заряд клетки становится менее отрицательным, затем резко меняется, после чего возвращается к исходному уровню. На вашем графике медленная и быстрая реполяризация — отдельные этапы; придерживайтесь именно этой схемы." },
{ id:5, topic:"membrane", title:"Изменение возбудимости во время фаз ПД", answer:"Во время быстрой деполяризации развивается абсолютная рефрактерность: новый ПД вызвать нельзя. Во время быстрой реполяризации — относительная рефрактерность: нужен более сильный стимул. На участке медленной реполяризации в используемой вами схеме отмечена супернормальная возбудимость; при гиперполяризации — субнормальная.", simple:"Сразу после запуска клетка не может ответить снова. Затем отвечает только на сильный стимул; на короткое время может стать чувствительнее обычного, а при гиперполяризации — менее чувствительной." },
{ id:6, topic:"membrane", title:"Проницаемость Na⁺-каналов: M- и H-ворота", answer:"При деполяризации активируются M-ворота Na⁺-канала и натрий входит в клетку. Затем H-ворота инактивируют канал. При восстановлении потенциала покоя канал возвращается в состояние готовности к активации.", simple:"У натриевого канала две створки: одна быстро открывается, другая закрывается с задержкой и временно не даёт каналу работать." },
{ id:7, topic:"irritation", title:"Закон силы для гомогенной системы", answer:"Для отдельного нервного или мышечного волокна действует принцип «всё или ничего»: подпороговый стимул не вызывает распространяющегося ПД, а пороговый и сверхпороговый вызывают ПД стандартной амплитуды.", simple:"Одиночное волокно либо запускает полноценный импульс, либо не запускает его. Сверхсильный стимул не делает отдельный ПД бесконечно больше." },
{ id:8, topic:"irritation", title:"Локальный ответ и потенциал действия: сравнение", answer:"Локальный ответ градуален, зависит от силы стимула и затухает с расстоянием; рефрактерного периода как у ПД не имеет. ПД возникает при достижении порога, распространяется без затухания и сопровождается рефрактерностью.", simple:"Локальный ответ — небольшой сигнал, который постепенно затухает. ПД — полноценный импульс, который проходит по мембране." },
{ id:9, topic:"irritation", title:"Закон силы для гетерогенной системы", answer:"В целом нерве или мышце увеличение силы раздражителя вовлекает больше волокон, поэтому суммарный ответ растёт до максимума. При максимальном раздражении активированы все доступные волокна.", simple:"Слабый стимул включает часть волокон, более сильный — больше. Когда включились все, дальнейшее усиление уже не увеличивает ответ." },
{ id:10, topic:"irritation", title:"Закон длительности. Кривая Гоорвега—Вейса—Лапика", answer:"Для возникновения возбуждения стимул должен иметь достаточную длительность. Чем выше сила раздражителя, тем меньше минимальное время, необходимое для возбуждения; зависимость отражает кривая сила—длительность.", simple:"Слабый толчок нужно прикладывать дольше, сильный — короче. Для возбуждения важны и сила, и время действия." },
{ id:11, topic:"irritation", title:"Реобаза, полезное время и хронаксия", answer:"Реобаза — минимальная сила тока, способная вызвать возбуждение при длительном воздействии. Полезное время — минимальная длительность воздействия током в одну реобазу. Хронаксия — минимальная длительность воздействия током силой в две реобазы. Чем короче хронаксия, тем выше возбудимость.", simple:"Реобаза — минимальная сила, полезное время — сколько нужно действовать этой силой, хронаксия — сколько нужно действовать током вдвое сильнее." },
{ id:12, topic:"irritation", title:"Хронаксиметрия и её медицинское значение", answer:"Хронаксиметрия — измерение хронаксии с помощью специального прибора. Метод применяют для оценки возбудимости нервно-мышечного аппарата; увеличение хронаксии может указывать на снижение возбудимости при повреждении нерва или мышечных нарушениях.", simple:"Прибор определяет, как долго нужно подействовать током, чтобы вызвать ответ. Чем дольше требуется воздействие, тем ниже возбудимость." },
{ id:13, topic:"irritation", title:"Закон градиента и аккомодация", answer:"Чем быстрее нарастает сила раздражителя, тем легче возникает возбуждение. При медленном нарастании порог повышается; ткань может приспособиться к стимулу — это аккомодация.", simple:"Резкое изменение клетка замечает, а к медленно нарастающему воздействию может приспособиться и не запустить ПД." },
{ id:14, topic:"irritation", title:"Закон частоты и лабильность", answer:"Лабильность — максимальная частота импульсов, которую ткань способна воспроизводить без искажений. В отдельном волокне частота ПД соответствует частоте стимуляции до предела лабильности; в целом нерве или мышце суммарный ответ зависит от вовлечения волокон.", simple:"Лабильность — максимальная скорость, с которой ткань успевает отвечать на повторные стимулы." },
{ id:15, topic:"irritation", title:"Оптимум и пессимум частоты", answer:"Оптимум — частота раздражения, вызывающая максимальный ответ. Пессимум — чрезмерно высокая частота, при которой ответ уменьшается или исчезает, в том числе из-за рефрактерности и недостаточного восстановления ткани.", simple:"При оптимальном ритме ответ самый сильный. Если подавать импульсы слишком часто, ткань не успевает восстановиться и отвечает хуже." },
{ id:16, topic:"irritation", title:"Законы действия постоянного тока (закон Пфлюгера)", answer:"При замыкании постоянного тока возбуждение обычно возникает под катодом; при размыкании — под анодом. Под катодом мембрана деполяризуется, а при прекращении действия анода происходит возврат потенциала, который может вызвать возбуждение.", simple:"Коротко для запоминания: катод — замыкание, анод — размыкание." },
{ id:17, topic:"irritation", title:"Катэлектротон, анэлектротон и катодическая депрессия", answer:"Катэлектротон — состояние под катодом с деполяризацией и первоначальным повышением возбудимости. Анэлектротон — состояние под анодом с гиперполяризацией и снижением возбудимости. При длительном действии катода возбудимость может снижаться из-за инактивации Na⁺-каналов — катодическая депрессия.", simple:"Краткое действие катода повышает готовность к возбуждению, анод снижает её. При длительном действии катода натриевые каналы инактивируются, и ткань перестаёт нормально отвечать." },
{ id:18, topic:"nerve", title:"Проведение возбуждения в безмиелиновых волокнах", answer:"Проведение непрерывное: локальные токи деполяризуют соседний участок мембраны до порога, где возникает новый ПД. В предоставленном конспекте для волокон типа C указана скорость около 0,5–2 м/с. Фактор надёжности связан с тем, что амплитуда ПД превышает порог, необходимый для возбуждения соседнего участка.", simple:"Импульс последовательно активирует каждый следующий участок мембраны. Это медленнее, чем проведение по миелиновому волокну." },
{ id:19, topic:"nerve", title:"Проведение возбуждения в миелинизированных волокнах", answer:"Проведение сальтаторное: ПД возникает в перехватах Ранвье, а локальный ток распространяется под миелином к следующему перехвату. В конспекте указана скорость примерно 3–120 м/с. Миелин ускоряет и делает проведение энергетически экономичнее.", simple:"Миелин работает как изоляция, поэтому импульс как бы перепрыгивает от одного перехвата Ранвье к следующему." },
{ id:20, topic:"nerve", title:"Законы проведения возбуждения по нервному волокну", answer:"Проведение требует анатомической и физиологической целостности волокна. Возбуждение проводится изолированно по каждому волокну и в эксперименте распространяется от места раздражения в обе стороны. В организме направленность рефлекторного пути задаётся синапсами.", simple:"Нерв должен быть физически целым и функционально работоспособным; соседние волокна не должны смешивать свои сигналы." },
{ id:21, topic:"nerve", title:"Эксперимент Эрлангера и Гассера. Классификация нервных волокон", answer:"Регистрация суммарного ответа смешанного нерва выявила волны A, B и C, связанные с разной скоростью проведения. Волокна A — миелинизированные и быстрые; B — тонкие миелинизированные, в том числе преганглионарные вегетативные; C — тонкие безмиелиновые, медленные.", simple:"В одном нерве есть волокна-«спринтеры» и более медленные волокна. Поэтому суммарный ответ приходит несколькими волнами." },
{ id:22, topic:"nerve", title:"Быстрый и медленный аксонный транспорт", answer:"Быстрый транспорт переносит, в частности, везикулы и органеллы; медленный — структурные белки и компоненты, необходимые для поддержания и роста аксона. Оба процесса обеспечивают снабжение нервного окончания и обновление аксона.", simple:"Быстрый транспорт — срочная доставка, медленный — доставка строительных материалов для поддержания и восстановления аксона." },
{ id:23, topic:"nerve", title:"Классификации и строение нейронов. Нейронография", answer:"По форме выделяют униполярные, биполярные и мультиполярные нейроны; по функции — афферентные, эфферентные и вставочные. Нейронография регистрирует импульсную активность нейронов с помощью электродов.", simple:"Нейроны различаются по форме и задаче: одни принимают сигналы, другие передают команды, третьи связывают нервные цепи." },
{ id:24, topic:"synapse", title:"Химический синапс и сравнение с электрическим", answer:"В химическом синапсе потенциал действия вызывает вход Ca²⁺ в пресинаптическое окончание, выделение медиатора и активацию рецепторов постсинаптической мембраны. Передача обычно односторонняя и имеет задержку. Электрические синапсы передают ток через щелевые контакты быстрее и могут проводить в обе стороны.", simple:"Химический синапс передаёт сигнал с помощью вещества-посредника; электрический — через прямую связь между клетками." },
{ id:25, topic:"synapse", title:"ВПСП, ТПСП, миниатюрные потенциалы и суммация", answer:"ВПСП — возбуждающий постсинаптический потенциал, который приближает мембрану к порогу; ТПСП снижает вероятность возбуждения. Суммация бывает временной (сигналы следуют друг за другом) и пространственной (сигналы приходят от разных синапсов). Миниатюрные потенциалы связаны со спонтанным выделением небольших порций медиатора.", simple:"ВПСП помогает приблизиться к запуску импульса, ТПСП противодействует ему. Несколько небольших сигналов могут сложиться." },
{ id:26, topic:"synapse", title:"Генерация ПД нейрона и соматодендритный потенциал", answer:"Возбуждающие и тормозные постсинаптические потенциалы суммируются в теле и дендритах нейрона. Если суммарная деполяризация достигает порога в области начального сегмента аксона, возникает ПД.", simple:"Дендриты собирают сигналы, а начальный участок аксона решает, достигнут ли порог для запуска импульса." },
{ id:27, topic:"synapse", title:"Распространение возбуждения в нейрональной сети", answer:"К основным принципам относятся дивергенция (один нейрон передаёт сигнал многим), конвергенция (многие нейроны воздействуют на один), иррадиация и реверберация (циркуляция возбуждения по замкнутым цепям).", simple:"Сигнал может расходиться к множеству клеток, собираться от множества клеток или циркулировать по цепи." },
{ id:28, topic:"synapse", title:"Нервно-мышечный синапс: механизм и свойства", answer:"ПД в нервном окончании вызывает вход Ca²⁺ и выделение ацетилхолина. Он связывается с рецепторами мышечной мембраны, вызывает потенциал концевой пластинки и запуск мышечного ПД, после чего начинается сокращение. Передача односторонняя и чувствительна к веществам, нарушающим выделение медиатора или работу рецепторов.", simple:"Нерв отдаёт мышце команду через ацетилхолин. Если заблокировать его выделение или рецепторы, мышца не получит сигнал к сокращению." },
{ id:29, topic:"muscle", title:"Режимы и виды мышечного сокращения. Одиночное сокращение", answer:"Основные режимы — изометрический (напряжение меняется без изменения длины) и изотонический (длина меняется при относительно постоянном напряжении). Одиночное сокращение включает латентный период, сокращение и расслабление.", simple:"Изометрия — мышца напрягается, но не укорачивается заметно; изотония — мышца меняет длину." },
{ id:30, topic:"muscle", title:"Электромеханическое сопряжение", answer:"Возбуждение распространяется по сарколемме и Т-трубочкам, запускает высвобождение Ca²⁺ из саркоплазматического ретикулума. Ca²⁺ связывается с тропонином, что позволяет актину и миозину взаимодействовать.", simple:"Электрический сигнал приводит к выходу кальция, а кальций разрешает мышечным нитям скользить друг относительно друга." },
{ id:31, topic:"muscle", title:"Теория скользящих нитей", answer:"Сила сокращения возникает при циклическом взаимодействии миозиновых головок с актином. Тонкие и толстые нити скользят друг относительно друга; сами нити существенно не укорачиваются.", simple:"Нити не сжимаются сами — они задвигаются глубже друг между другом, и саркомер становится короче." },
{ id:32, topic:"muscle", title:"Саркомер и его изменения при сокращении", answer:"Саркомер — участок миофибриллы между Z-линиями. При сокращении Z-линии сближаются, I-полосы и H-зона уменьшаются, а ширина A-полосы остаётся примерно постоянной.", simple:"При сокращении границы саркомера сближаются; зоны, где нити только одного типа, становятся уже." },
{ id:33, topic:"muscle", title:"Тетаническое сокращение", answer:"При частых повторных раздражениях одиночные сокращения суммируются. Различают зубчатый и гладкий тетанус; чрезмерная частота может привести к пессимальному снижению ответа.", simple:"Если следующий импульс приходит до полного расслабления мышцы, сокращения складываются и сила растёт." },
{ id:34, topic:"muscle", title:"Физиология утомления", answer:"Утомление — временное снижение работоспособности при длительной или интенсивной деятельности. Вклад могут вносить изменения передачи в синапсах, энергетического обеспечения, ионного баланса и сократительного аппарата.", simple:"Мышца и нервная система временно хуже поддерживают прежнюю силу и частоту работы после нагрузки." },
{ id:35, topic:"muscle", title:"Физиология гладкой мышцы", answer:"Гладкая мышца сокращается медленнее скелетной, может проявлять автоматизм и пластичность. Ca²⁺ связывается с кальмодулином; тропониновая регуляция, характерная для скелетной мышцы, отсутствует.", simple:"Гладкая мышца работает медленнее и использует кальмодулин вместо тропонина." },
{ id:36, topic:"muscle", title:"Двигательная единица и её классификация", answer:"Двигательная единица — мотонейрон и все мышечные волокна, которые он иннервирует. Различают медленные и быстрые двигательные единицы, отличающиеся скоростью, устойчивостью к утомлению и развиваемой силой.", simple:"Один мотонейрон вместе с управляемыми им мышечными волокнами — одна двигательная единица." },
{ id:37, topic:"muscle", title:"Регуляция силы сокращения целой мышцы", answer:"Сила целой мышцы регулируется вовлечением дополнительных двигательных единиц и изменением частоты импульсации мотонейронов, что приводит к суммации сокращений.", simple:"Чтобы мышца развила большую силу, нервная система подключает больше двигательных единиц и/или посылает импульсы чаще." },
{ id:38, topic:"muscle", title:"Методы исследования мышц: ЭМГ", answer:"Электромиография (ЭМГ) регистрирует электрическую активность мышц и используется для оценки состояния двигательных единиц, нервно-мышечной передачи и мышечной функции.", simple:"ЭМГ записывает электрические сигналы мышц — по ним оценивают, как работает нервно-мышечная система." },
];


type SituationalTask = { id: number; topic: string; title: string; question: string; answer: string; simple: string };
const situationalTasks: SituationalTask[] = [
{ id:1, topic:"membrane", title:"Тетродотоксин", question:"Нервно-мышечный препарат поместили в раствор с тетродотоксином, блокирующим потенциал-зависимые Na⁺-каналы. Как изменятся ПП и ПД?", answer:"ПП вначале существенно не изменится, а генерация и проведение ПД будут заблокированы.", simple:"В покое натриевые каналы почти закрыты, поэтому ПП поддерживается в основном другими механизмами. Для ПД нужен быстрый вход Na⁺ — токсин блокирует этот путь."},
{ id:2, topic:"membrane", title:"Блокада Na⁺/K⁺-насоса", question:"Как изменятся ПП, ПД и возбудимость при длительной блокаде натрий-калиевого насоса?", answer:"Ионные градиенты постепенно уменьшаются, ПП деполяризуется, генерация ПД и возбудимость со временем нарушаются.", simple:"Насос поддерживает разницу концентраций Na⁺ и K⁺. При его отключении клетка постепенно теряет условия для нормального импульса."},
{ id:3, topic:"membrane", title:"Батрахотоксин", question:"Яд повышает проницаемость мембраны для Na⁺ в покое. Что произойдёт с ПП?", answer:"ПП станет менее отрицательным: возникнет деполяризация.", simple:"Положительный натрий входит в клетку и уменьшает отрицательный заряд внутри."},
{ id:4, topic:"irritation", title:"Частота и рефрактерность", question:"Нерв раздражают с частотой 1000 Гц, абсолютный рефрактерный период равен 2 мс. Какова предельная частота ответов по этому расчёту?", answer:"500 Гц: 1000 / 2 мс = 500 Гц.", simple:"Пока длится рефрактерность, новый полноценный ПД не возникает. Поэтому нерв не успевает отвечать на каждый стимул."},
{ id:5, topic:"membrane", title:"Изменение КУД на 30%", question:"ПП = −90 мВ, КУД = −60 мВ. Как изменится возбудимость, если КУД сдвинется на 30% от исходного значения к нулю?", answer:"Возбудимость снизится: расстояние от ПП до нового порога станет больше.", simple:"Изначальная разница составляет 30 мВ. Если порог сдвигается к −42 мВ, разница становится 48 мВ — клетке нужно сильнее деполяризоваться."},
{ id:6, topic:"membrane", title:"Подпороговый ответ", question:"Порог деполяризации равен 20 мВ, а ответ мембраны составляет 18 мВ. Как называется такой ответ?", answer:"Локальный (градуальный) подпороговый ответ; распространяющийся ПД не возникает.", simple:"Ответ не достиг порога. Он зависит от силы раздражителя и затухает, в отличие от ПД."},
{ id:7, topic:"membrane", title:"Сдвиг КУД", question:"КУД изменился с −60 до −50 мВ при неизменном ПП. Как изменилась возбудимость?", answer:"Снизилась, поскольку мембране требуется большая деполяризация для достижения порога.", simple:"Порог приблизился к нулю, а разница между ПП и КУД увеличилась."},
{ id:8, topic:"irritation", title:"Расчёт лабильности", question:"Рефрактерный период нервного волокна равен 2 мс. Рассчитайте лабильность по формуле 1000 / период в миллисекундах.", answer:"500 Гц.", simple:"1000 делим на 2 мс. Это теоретическая предельная частота по заданному рефрактерному периоду."},
{ id:9, topic:"nerve", title:"Регенерация нерва", question:"Нерв длиной 45 см повреждён на границе верхней и средней трети. Оцените срок отрастания при скорости 1 мм/сутки, если нужно восстановить около 30 см.", answer:"Около 300 суток (300 мм ÷ 1 мм/сутки). Это оценка по заданной скорости, а не универсальный клинический прогноз.", simple:"Переводим 30 см в 300 мм и делим на суточную скорость роста."},
{ id:10, topic:"irritation", title:"Диатермия и высокочастотный ток", question:"Почему переменный ток высокой частоты при диатермии может нагревать ткани, но не вызывать обычного возбуждения при каждом цикле?", answer:"Каждый полупериод слишком короток, чтобы мембранный потенциал достиг порога; энергия рассеивается в тканях в виде тепла.", simple:"Для возбуждения важны не только сила, но и длительность раздражения. Очень быстрые смены направления не дают мембране сформировать ПД."},
{ id:11, topic:"irritation", title:"Оценка хронаксии", question:"Норма хронаксии двуглавой мышцы — 0,0016 с, трёхглавой — 0,002 с. У испытуемого — 0,002 и 0,004 с. Как оценить результат?", answer:"Хронаксия обеих мышц увеличена, следовательно, их возбудимость снижена.", simple:"Чем больше время, необходимое для возбуждения током в две реобазы, тем ниже возбудимость."},
{ id:12, topic:"membrane", title:"Местный анестетик", question:"Анестетик увеличил долю инактивированных Na⁺-каналов. Что произойдёт с ПД?", answer:"Быстрая деполяризация и амплитуда ПД уменьшатся; при выраженной блокаде ПД и проведение могут исчезнуть. ПП обычно меняется мало.", simple:"Меньше доступных натриевых каналов — меньше входящий ток Na⁺ и слабее импульс."},
{ id:13, topic:"irritation", title:"Перевязанный нерв и постоянный ток", question:"Нерв перевязан между электродами; мышца сокращается только при замыкании цепи. Какой электрод ближе к мышце?", answer:"Катод.", simple:"При замыкании постоянного тока возбуждение обычно возникает под катодом. Перевязка не позволяет импульсу пройти с другого участка."},
{ id:14, topic:"synapse", title:"Пространственная суммация", question:"Возникнет ли возбуждение нейрона, если по нескольким аксонам одновременно поступают подпороговые сигналы?", answer:"Может возникнуть, если суммарная деполяризация достигнет порога: это пространственная суммация ВПСП.", simple:"Несколько слабых сигналов складываются и могут вместе запустить ПД."},
{ id:15, topic:"nerve", title:"Возбудимость частей нейрона", question:"Порог раздражения равен 100, 30 и 10 мВ. Распределите значения между дендритами, сомой и аксонным холмиком.", answer:"100 мВ — дендриты; 30 мВ — сома; 10 мВ — аксонный холмик.", simple:"Чем ниже порог, тем выше возбудимость. Аксонный холмик обычно имеет самый низкий порог генерации ПД."},
{ id:16, topic:"nerve", title:"Скорость проведения по волокну", question:"Импульс проходит 20 см за 100 мс. Рассчитайте скорость и укажите характерный тип волокна.", answer:"v = 0,2 м / 0,1 с = 2 м/с; это соответствует медленному проведению, характерному для волокон типа C в учебном примере.", simple:"Переводим сантиметры в метры, миллисекунды в секунды и делим путь на время."},
{ id:17, topic:"nerve", title:"Быстрое нервное волокно", question:"Импульс проходит 20 см за 2 мс. Рассчитайте скорость.", answer:"v = 0,2 м / 0,002 с = 100 м/с; это характерно для быстрого миелинизированного волокна типа A.", simple:"Короткое время на том же расстоянии означает большую скорость проведения."},
{ id:18, topic:"synapse", title:"ЭДТА и нервно-мышечная передача", question:"После обработки нервно-мышечного синапса ЭДТА потенциал концевой пластинки не возник. Почему?", answer:"ЭДТА связывает Ca²⁺; без поступления Ca²⁺ в пресинаптическое окончание нарушается выброс ацетилхолина.", simple:"Кальций нужен для слияния везикул с мембраной. Нет кальция — нет нормального выделения медиатора."},
{ id:19, topic:"synapse", title:"Ботулотоксин", question:"Почему ботулотоксин может вызвать опасный для жизни паралич?", answer:"Он нарушает высвобождение ацетилхолина из пресинаптических окончаний; при поражении дыхательных мышц возникает дыхательная недостаточность.", simple:"Нервный сигнал доходит до окончания, но команда не передаётся мышце."},
{ id:20, topic:"synapse", title:"Гемихолиний", question:"Как повлияет гемихолиний, угнетающий захват холина пресинаптическим окончанием?", answer:"Синтез ацетилхолина уменьшится, поэтому нервно-мышечная передача ослабнет.", simple:"Холин нужен для повторного синтеза ацетилхолина. Если его захват блокирован, запас медиатора постепенно истощается."},
{ id:21, topic:"synapse", title:"Миастения", question:"Почему антихолинэстеразные препараты могут улучшать передачу при уменьшении числа холинорецепторов?", answer:"Они тормозят разрушение ацетилхолина, продлевая его действие на оставшиеся рецепторы.", simple:"Медиатор дольше остаётся в синаптической щели и получает больше шансов связаться с доступными рецепторами."},
{ id:22, topic:"muscle", title:"Движения при поверхностном наркозе", question:"Как в условиях задачи предотвратить непроизвольные движения и повышение мышечного тонуса при поверхностном наркозе?", answer:"В учебном сценарии — применением периферического миорелаксанта по медицинским показаниям и под контролем анестезиолога.", simple:"Миорелаксант блокирует нервно-мышечную передачу. Это клиническое решение требует профессионального контроля и не является советом для самостоятельного применения."},
{ id:23, topic:"muscle", title:"Растяжение саркомера", question:"Как изменится ширина H-зоны саркомера при растяжении мышцы?", answer:"H-зона увеличится.", simple:"При растяжении перекрытие актиновых и миозиновых нитей уменьшается; центральная зона без актина становится шире."},
{ id:24, topic:"muscle", title:"Трупное окоченение", question:"Когда быстрее наступает трупное окоченение: при предварительном угнетении тканевого дыхания или без него?", answer:"При угнетении тканевого дыхания, когда запасы АТФ быстрее истощаются.", simple:"Без АТФ миозиновые головки не могут нормально отсоединяться от актина, поэтому мышца остаётся ригидной."},
{ id:25, topic:"muscle", title:"Мочеточник и артерия", question:"Как в растворе Рингера отличить фрагмент мочеточника от фрагмента крупной артерии без внешнего осмотра?", answer:"В учебной задаче у мочеточника ожидаются спонтанные ритмичные сокращения благодаря автоматии гладкой мышцы.", simple:"Мочеточник продвигает содержимое перистальтическими сокращениями. Ответ реального препарата зависит от условий эксперимента."},
{ id:26, topic:"muscle", title:"Мочеточник и артерия в растворе Рингера", question:"Взяли фрагменты мочеточника и крупной артерии и поместили в раствор Рингера. Как различить их без внешнего осмотра?", answer:"В условиях учебной задачи мочеточник будет проявлять спонтанные ритмичные сокращения благодаря автоматии гладкой мышцы.", simple:"Мочеточник способен к перистальтическим сокращениям. Это ожидаемый признак в описанном опыте; фактическая реакция зависит от состояния ткани и условий эксперимента."}
];


type BankQuestion = { id: number; module: string; question: string; answer: string; why: string; number?: number; options?: { number: number; text: string }[]; whyLabel?: string };
const testModules = [
  { id: "intro", title: "Основы физиологии и функциональные системы", range: "1–36" },
  ...physiologyTestData.map(section => ({ id: section.id, title: section.title, range: `1–${section.questions.length}` })),
];
const introTestBank: BankQuestion[] = [
{ id:1,module:"intro",question:"Основоположник теории функциональных систем:",answer:"П.К. Анохин.",why:"Он разработал концепцию функциональных систем, объединённых ради полезного результата."},
{ id:2,module:"intro",question:"Кто сформулировал понятие биологической системы?",answer:"Л. фон Берталанфи.",why:"Он создал общую теорию систем."},
{ id:3,module:"intro",question:"Как называется динамическая саморегулирующаяся система, компоненты которой взаимодействуют ради полезного результата?",answer:"Функциональная система.",why:"Это центральное понятие теории П. К. Анохина."},
{ id:4,module:"intro",question:"Какой элемент в архитектонике функциональной системы указан в исходном разборе как наиболее консервативный?",answer:"Рецепторный аппарат (ответ приведён в разборе исходного материала).",why:"Сверяйте формулировку с ключом и вариантами на странице пособия: в переданном текстовом разборе этот пункт отмечен как требующий проверки."},
{ id:5,module:"intro",question:"Кому принадлежит инициативная роль при первоначальном объединении органов в функциональную систему?",answer:"Потребности.",why:"Функциональная система формируется для удовлетворения актуальной биологической или социальной потребности."},
{ id:6,module:"intro",question:"Чем определяется вид функциональной системы?",answer:"Видом потребности.",why:"Например, потребности в пище и воде требуют разных функциональных систем."},
{ id:7,module:"intro",question:"Каково значение канала обратной связи в функциональной системе?",answer:"Постоянная оценка эффективности удовлетворения потребности.",why:"Обратная связь сообщает системе, достигнут ли полезный результат."},
{ id:8,module:"intro",question:"Какова последовательность саморегуляции «по рассогласованию»?",answer:"Отклонение константы → рецепторный аппарат → канал обратной связи → нервный центр → канал прямой связи → изменение работы органов → восстановление показателя.",why:"Система сначала обнаруживает отклонение, затем передаёт информацию центру и корректирует работу исполнительных органов."},
{ id:9,module:"intro",question:"Какова последовательность саморегуляции «по возмущению» в приведённом разборе?",answer:"Воздействие факторов внешней среды → переход центров на новый уровень → изменение аппарата контроля → включение прямой связи → изменение работы органов → изменение показателя.",why:"В этом варианте система перестраивается в ответ на ожидаемое внешнее воздействие; последовательность следует сверять с ключом пособия."},
{ id:10,module:"intro",question:"Какой элемент функциональной системы в исходном разборе назван наиболее пластичным?",answer:"Исполнительный орган.",why:"Работа исполнительных органов может меняться в зависимости от требований системы."},
{ id:11,module:"intro",question:"Каков конечный полезный результат гомеостатической функциональной системы?",answer:"Оптимальный параметр внутренней среды.",why:"Например, поддержание температуры, pH или другого параметра в допустимом диапазоне."},
{ id:12,module:"intro",question:"Каков конечный полезный результат метаболической функциональной системы?",answer:"Продукт обмена веществ.",why:"Результатом может быть образование необходимого организму продукта метаболизма."},
{ id:13,module:"intro",question:"Каков конечный полезный результат поведенческой функциональной системы?",answer:"Удовлетворение биологической или социальной потребности.",why:"Поведение приводит к результату, который устраняет соответствующую потребность."},
{ id:14,module:"intro",question:"Какую роль в функциональной системе выполняют миоциты и железистые клетки?",answer:"Исполнительные элементы.",why:"Они реализуют команды через сокращение или секрецию."},
{ id:15,module:"intro",question:"Какую функцию выполняют эфферентные нервы и биологически активные вещества?",answer:"Каналы прямой связи.",why:"Они передают управляющее воздействие от центра к исполнительным органам."},
{ id:16,module:"intro",question:"Что в исходном разборе указано как элемент, контролирующий состояние результата и осуществляющий его коррекцию?",answer:"Нервный центр (по приведённому ключу).",why:"Центр сопоставляет поступающую информацию и организует корректирующее воздействие."},
{ id:17,module:"intro",question:"Что включает «следящее устройство» функциональной системы?",answer:"Рецепторный аппарат и канал обратной связи.",why:"Рецепторы регистрируют результат, а обратная связь передаёт сведения для оценки."},
{ id:18,module:"intro",question:"Какое свойство обеспечивает единый принцип построения функциональных систем?",answer:"Изоморфизм.",why:"Системы разного назначения могут иметь общий принцип организации."},
{ id:19,module:"intro",question:"Как называется способность системы формировать новое свойство, не присущее отдельным элементам?",answer:"Эмерджентность.",why:"Совместная работа компонентов создаёт свойства целого, которых нет у каждого компонента по отдельности."},
{ id:20,module:"intro",question:"Как называется раздражитель, к которому рецептор приспособлен эволюционно?",answer:"Адекватный раздражитель.",why:"Например, свет является адекватным раздражителем для фоторецепторов."},
{ id:21,module:"intro",question:"Какому возрасту соответствует неонатальный период по приведённому тестовому разбору?",answer:"Периоду новорождённости — до 1 месяца.",why:"Неонатальный период охватывает первый месяц жизни."},
{ id:22,module:"intro",question:"Какой возрастной диапазон пубертатного периода для девочек указан в исходном разборе?",answer:"12–15 лет.",why:"Это значение приведено в переданном разборе тестового ключа; для экзамена используйте диапазон из своего пособия."},
{ id:23,module:"intro",question:"Какой возрастной диапазон пубертатного периода для мальчиков указан в исходном разборе?",answer:"13–16 лет.",why:"Это значение приведено в переданном разборе тестового ключа; возрастные границы могут зависеть от принятой классификации."},
{ id:24,module:"intro",question:"Какой ответ приведён в исходном разборе для особенности возрастного системогенеза?",answer:"Автоматизация систем (ответ по приведённому ключу; пункт отмечен в исходнике как требующий сверки).",why:"В самом переданном тексте отмечено возможное расхождение с принципом минимального обеспечения функции — обязательно сверить с оригинальным вариантом вопроса."},
{ id:25,module:"intro",question:"На что направлен пренатальный системогенез согласно исходному разбору?",answer:"На обеспечение адаптации новорождённого к условиям внешней среды.",why:"Созревание ряда систем до рождения подготавливает организм к самостоятельной жизни."},
{ id:26,module:"intro",question:"Какой возрастной диапазон юношеского возраста для девушек указан в исходном разборе?",answer:"16–20 лет.",why:"Это значение приведено в текстовом разборе исходного материала."},
{ id:27,module:"intro",question:"С какого возраста начинается второй период зрелого возраста по приведённому ключу?",answer:"С 36 лет.",why:"В исходном разборе приведены границы 36–60 лет для мужчин и 36–55 лет для женщин."},
{ id:28,module:"intro",question:"До какого возраста длится первый период зрелого возраста по приведённому ключу?",answer:"До 35 лет.",why:"Ответ следует классификации возрастных периодов, приведённой в разборе пособия."},
{ id:29,module:"intro",question:"С какого возраста начинается пожилой возраст у мужчин по приведённому ключу?",answer:"После 60 лет.",why:"Это граница, указанная в исходном текстовом разборе."},
{ id:30,module:"intro",question:"С какого возраста начинается пожилой возраст у женщин по приведённому ключу?",answer:"После 55 лет.",why:"Это граница, указанная в исходном текстовом разборе."},
{ id:31,module:"intro",question:"С какого возраста, согласно приведённому ключу, начинается старческий возраст?",answer:"С 75 лет.",why:"Ответ воспроизводит возрастную классификацию из исходного разбора."},
{ id:32,module:"intro",question:"С какого возраста по приведённому ключу человека относят к долгожителям?",answer:"Свыше 90 лет.",why:"Это значение указано в исходном разборе тестов."},
{ id:33,module:"intro",question:"Что такое системогенез?",answer:"Последовательное и избирательное созревание функциональных систем в онтогенезе.",why:"Разные системы созревают не одновременно, а в соответствии с этапами развития."},
{ id:34,module:"intro",question:"Что означает принцип иерархии функциональных систем?",answer:"Соподчинение систем низшего уровня более сложным.",why:"Работа отдельных уровней согласуется с задачами более крупных систем."},
{ id:35,module:"intro",question:"Что означает мультипараметрический принцип взаимодействия?",answer:"Обобщённая деятельность на основе взаимодействия нескольких показателей полезного результата.",why:"Организм оценивает не один показатель изолированно, а согласует несколько параметров."},
{ id:36,module:"intro",question:"Что означает последовательное взаимодействие функциональных систем?",answer:"Каскадное взаимодействие конечных результатов систем.",why:"Результат одной системы может становиться условием запуска следующей."},
];

const quiz = [
 {q:"Что преимущественно выходит из клетки и вносит вклад в формирование потенциала покоя?", options:["Na⁺","K⁺","Ca²⁺","Cl⁻"], correct:1, why:"В покое мембрана обычно значительно проницаемее для K⁺, который выходит по электрохимическому градиенту."},
 {q:"Что происходит при достижении критического уровня деполяризации?", options:["Немедленно прекращается любой транспорт ионов","Запускается регенеративный потенциал действия","Мембрана навсегда становится непроницаемой","Сразу наступает мышечное утомление"], correct:1, why:"Пороговая деполяризация активирует потенциал-зависимые каналы и запускает ПД."},
 {q:"Какая фаза соответствует абсолютной рефрактерности в схеме вашего конспекта?", options:["Медленная деполяризация","Быстрая деполяризация","Гиперполяризация","Покой после полного восстановления"], correct:1, why:"Во время быстрой деполяризации значительная часть Na⁺-каналов находится в активированном/инактивированном цикле, поэтому новый ПД вызвать нельзя."},
 {q:"Что называют хронаксией?", options:["Минимальную силу длительного тока","Минимальное время действия тока силой в две реобазы","Максимальную частоту импульсов","Скорость проведения по аксону"], correct:1, why:"Хронаксия — минимальная длительность воздействия током в две реобазы, достаточная для возбуждения."},
 {q:"Что означает аккомодация?", options:["Приспособление ткани к медленно нарастающему раздражителю","Скачкообразное проведение по миелину","Суммирование сокращений","Выделение медиатора в синапсе"], correct:0, why:"При медленном нарастании раздражителя порог повышается и возбуждение может не возникнуть."},
 {q:"Где в миелинизированном волокне обычно регенерируется потенциал действия?", options:["По всей поверхности миелина равномерно","В перехватах Ранвье","Только в теле нейрона","Только в мышечном волокне"], correct:1, why:"Перехваты Ранвье содержат высокую плотность потенциал-зависимых каналов; между ними ток распространяется под миелином."},
 {q:"Как обычно передаётся сигнал через химический синапс?", options:["Прямым перетеканием тока через нексус","Выделением медиатора и его связыванием с рецепторами","Скольжением актиновых нитей","Работой только натрий-калиевого насоса"], correct:1, why:"Химическая передача использует медиатор, который высвобождается пресинаптически и действует на постсинаптические рецепторы."},
 {q:"Чем отличаются временная и пространственная суммация?", options:["Временная — сигналы подряд во времени; пространственная — от разных входов","Временная — только в мышце; пространственная — только в нерве","Это два названия одного процесса","Временная происходит только в покое"], correct:0, why:"Временная суммация складывает эффекты последовательных сигналов, пространственная — сигналов от разных синапсов."},
 {q:"Что связывает Ca²⁺ в регуляции сокращения скелетной мышцы?", options:["Кальмодулин","Тропонин","Ацетилхолинэстераза","Миелин"], correct:1, why:"В скелетной мышце Ca²⁺ связывается с тропонином, перемещая тропомиозин и открывая участки взаимодействия актина с миозином."},
 {q:"Что регистрирует электромиография?", options:["Только артериальное давление","Электрическую активность мышц","Концентрацию глюкозы","Скорость фильтрации в почках"], correct:1, why:"ЭМГ регистрирует электрические сигналы мышц и помогает оценивать нервно-мышечную функцию."}
];
const sourceTestBank: BankQuestion[] = physiologyTestData.flatMap((section, sectionIndex) => section.questions.map(q => ({
  id: 37 + physiologyTestData.slice(0, sectionIndex).reduce((sum, item) => sum + item.questions.length, 0) + q.number - 1,
  module: section.id, number: q.number, question: q.question, options: q.options,
  answer: q.correct.map(n => { const option = q.options.find(item => item.number === n); return option ? `${n}) ${option.text}` : `${n})`; }).join("; "),
  why: "В методичке приведён эталон правильного варианта; отдельное пояснение к этому тесту в источнике не дано.", whyLabel: "Примечание к источнику",
})));
const testBank: BankQuestion[] = [...introTestBank, ...sourceTestBank];

export default function PhysiologyColloquiumPage({ params }: { params: Promise<{ id: string }> }) {
  const [subjectId, setSubjectId] = useState("");
  const [activeTopic, setActiveTopic] = useState("all");
  const [search, setSearch] = useState("");
  const [opened, setOpened] = useState<Record<number, boolean>>({});
  const [view, setView] = useState<"topics" | "questions" | "tasks" | "quiz" | "testBank">("topics");
  const [activeTestModule, setActiveTestModule] = useState("intro");
  const [answers, setAnswers] = useState<Record<number, number>>({});
  const [checked, setChecked] = useState(false);
  useEffect(() => { let cancelled = false; void params.then(p => { if (!cancelled) setSubjectId(p.id); }); return () => { cancelled = true; }; }, [params]);
  const filtered = useMemo(() => questions.filter(q => (activeTopic === "all" || q.topic === activeTopic) && (!search || (q.title + " " + q.answer).toLowerCase().includes(search.toLowerCase()))), [activeTopic, search]);
  const score = quiz.reduce((n, q, i) => n + (answers[i] === q.correct ? 1 : 0), 0);
  return <div className="mx-auto max-w-6xl space-y-6">
    <Link href={"/subjects/" + encodeURIComponent(subjectId)} className="inline-flex items-center gap-2 text-sm font-semibold text-indigo-700 hover:underline"><ArrowLeft className="h-4 w-4"/>К предмету</Link>
    <header className="rounded-3xl border border-indigo-100 bg-gradient-to-br from-indigo-50 via-white to-violet-50 p-6 sm:p-8">
      <div className="flex items-center gap-2 text-xs font-bold uppercase tracking-wider text-indigo-600"><GraduationCap className="h-4 w-4"/>Физиология · самоподготовка</div>
      <h1 className="mt-2 text-3xl font-black tracking-tight text-slate-900">Коллоквиум</h1>
      <p className="mt-2 max-w-3xl text-sm leading-6 text-slate-600">Темы, контрольные вопросы с ответами и объяснениями простыми словами, а также проверочный тест. Материал организован по разделам пособия «Физиология возбудимых систем».</p>
      <div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-3"><div className="rounded-2xl border border-white bg-white/80 p-4"><BookOpen className="h-5 w-5 text-indigo-600"/><div className="mt-2 text-2xl font-extrabold">38</div><div className="text-xs text-slate-500">контрольных вопросов</div></div><div className="rounded-2xl border border-white bg-white/80 p-4"><CircleHelp className="h-5 w-5 text-violet-600"/><div className="mt-2 text-2xl font-extrabold">{quiz.length}</div><div className="text-xs text-slate-500">вопросов в стартовом тесте</div></div><div className="col-span-2 rounded-2xl border border-white bg-white/80 p-4 sm:col-span-1"><CheckCircle2 className="h-5 w-5 text-emerald-600"/><div className="mt-2 text-sm font-bold">Ответ + объяснение</div><div className="text-xs text-slate-500">в каждой карточке</div></div></div>
    </header>
    <nav className="flex flex-wrap gap-2" aria-label="Разделы коллоквиума">
      {([{id:"topics",label:"Темы"},{id:"questions",label:"Вопросы и ответы"},{id:"tasks",label:"Ситуационные задачи"},{id:"testBank",label:`Банк тестов (${testBank.length})`},{id:"quiz",label:"Проверочный тест"}] as const).map(t=><button key={t.id} onClick={()=>setView(t.id)} className={"rounded-xl border px-4 py-2.5 text-sm font-bold "+(view===t.id?"border-indigo-600 bg-indigo-600 text-white":"border-slate-200 bg-white text-slate-700 hover:bg-slate-50")}>{t.label}</button>)}
    </nav>
    {view==="topics" && <section className="grid gap-3 md:grid-cols-2">{topics.map(t=><button key={t.id} onClick={()=>{setActiveTopic(t.id);setView("questions");}} className="card flex items-start gap-4 p-5 text-left transition hover:border-indigo-200 hover:shadow-sm"><div className="rounded-xl bg-indigo-50 p-3 text-indigo-700"><BookOpen className="h-5 w-5"/></div><div className="min-w-0 flex-1"><div className="font-bold text-slate-900">{t.title}</div><p className="mt-1 text-sm text-slate-600">{t.description}</p><div className="mt-3 text-xs font-semibold text-indigo-700">Вопросы {t.range} · открыть →</div></div></button>)}</section>}
    {view==="questions" && <section className="space-y-4">
      <div className="card space-y-3 p-4"><div className="flex flex-wrap gap-2">{[{id:"all",title:"Все темы"},...topics].map(t=><button key={t.id} onClick={()=>setActiveTopic(t.id)} className={"rounded-lg border px-3 py-2 text-xs font-bold "+(activeTopic===t.id?"border-indigo-500 bg-indigo-50 text-indigo-700":"border-slate-200 text-slate-600")}>{t.title}</button>)}</div><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Найти вопрос или термин…" className="w-full rounded-xl border border-slate-200 px-3 py-2.5 text-sm outline-none focus:border-indigo-400"/></div>
      <div className="text-sm text-slate-500">Найдено вопросов: {filtered.length}</div>
      {filtered.map(q=><article key={q.id} className="card overflow-hidden"><button onClick={()=>setOpened(s=>({...s,[q.id]:!s[q.id]}))} className="flex w-full items-start gap-3 p-4 text-left sm:p-5"><span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-indigo-50 text-sm font-extrabold text-indigo-700">{q.id}</span><span className="min-w-0 flex-1"><span className="block font-bold text-slate-900">{q.title}</span><span className="mt-1 block text-xs text-slate-500">{topics.find(t=>t.id===q.topic)?.title}</span></span><ChevronDown className={"mt-1 h-4 w-4 shrink-0 transition "+(opened[q.id]?"rotate-180":"")}/></button>{opened[q.id]&&<div className="space-y-4 border-t border-slate-100 bg-slate-50/60 p-4 sm:p-5"><div><h3 className="text-xs font-extrabold uppercase tracking-wide text-indigo-700">Правильный ответ</h3><p className="mt-2 whitespace-pre-line text-sm leading-6 text-slate-700">{q.answer}</p></div><div className="rounded-xl border border-emerald-100 bg-emerald-50/70 p-4"><h3 className="text-xs font-extrabold uppercase tracking-wide text-emerald-800">Простыми словами</h3><p className="mt-2 text-sm leading-6 text-emerald-950">{q.simple}</p></div></div>}</article>)}
    </section>}

    {view==="testBank" && <section className="space-y-4">
      <div className="card p-4 sm:p-5">
        <div className="flex flex-wrap items-start justify-between gap-3">
          <div><h2 className="font-bold text-slate-900">Банк тестовых заданий</h2><p className="mt-1 text-sm leading-5 text-slate-600">В банке собраны 36 заданий по функциональным системам и 253 теста из четырёх тем методички. Варианты ответов перенесены из источника, ключи сверены с таблицами эталонов; ответы раскрываются отдельно.</p></div>
          <span className="rounded-xl bg-indigo-50 px-3 py-2 text-sm font-extrabold text-indigo-700">{testBank.length} заданий</span>
        </div>
        <div className="mt-4 flex flex-wrap gap-2">{testModules.map(m=><button key={m.id} onClick={()=>setActiveTestModule(m.id)} className={"rounded-lg border px-3 py-2 text-xs font-bold "+(activeTestModule===m.id?"border-indigo-500 bg-indigo-50 text-indigo-700":"border-slate-200 text-slate-600")}>{m.title} · {m.range}</button>)}</div>
      </div>
      {testBank.filter(q=>q.module===activeTestModule).map(q=><article key={q.id} className="card overflow-hidden">
        <div className="p-4 sm:p-5"><div className="flex items-start gap-3"><span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-violet-50 text-sm font-extrabold text-violet-700">{q.number ?? q.id}</span><div className="min-w-0 flex-1"><h3 className="font-bold text-slate-900">{q.question}</h3>{q.options && <ol className="mt-3 space-y-1.5 text-sm leading-5 text-slate-700">{q.options.map(option => <li key={option.number} className="flex gap-2"><span className="font-semibold text-slate-500">{option.number})</span><span>{option.text.replace(/[;.]$/, "")}</span></li>)}</ol>}<details className="mt-3 rounded-xl border border-slate-200 bg-slate-50 p-3"><summary className="cursor-pointer text-sm font-bold text-indigo-700">Показать ответ и пояснение</summary><div className="mt-3"><div className="text-xs font-extrabold uppercase tracking-wide text-indigo-700">Ответ</div><p className="mt-1 text-sm leading-6 text-slate-700">{q.answer}</p><div className="mt-3 text-xs font-extrabold uppercase tracking-wide text-emerald-800">{q.whyLabel ?? "Простыми словами"}</div><p className="mt-1 text-sm leading-6 text-slate-700">{q.why}</p></div></details></div></div></div>
      </article>)}
      <div className="card flex flex-wrap items-center justify-between gap-3 p-4"><p className="text-sm text-slate-600">Всего 289 заданий: 36 по основам функциональных систем и 253 задания из методички (68 + 47 + 54 + 84).</p><button onClick={()=>setView("quiz")} className="rounded-xl bg-indigo-600 px-4 py-2.5 text-sm font-bold text-white hover:bg-indigo-700">Перейти к проверочному тесту</button></div>
    </section>}
    {view==="quiz" && <section className="space-y-4"><div className="card flex flex-wrap items-center justify-between gap-3 p-4"><div><h2 className="font-bold">Проверка знаний</h2><p className="text-sm text-slate-500">Выбери один ответ в каждом вопросе, затем проверь результат.</p></div><button onClick={()=>{setAnswers({});setChecked(false);}} className="inline-flex items-center gap-2 rounded-xl border px-3 py-2 text-sm font-semibold"><RotateCcw className="h-4 w-4"/>Сбросить</button></div>{quiz.map((q,i)=><article key={i} className="card p-4 sm:p-5"><div className="font-bold">{i+1}. {q.q}</div><div className="mt-3 grid gap-2">{q.options.map((option,j)=><label key={option} className={"flex cursor-pointer items-start gap-3 rounded-xl border p-3 text-sm "+(checked&&j===q.correct?"border-emerald-300 bg-emerald-50":answers[i]===j?"border-indigo-300 bg-indigo-50":"border-slate-200")}><input type="radio" name={"quiz-"+i} checked={answers[i]===j} disabled={checked} onChange={()=>setAnswers(a=>({...a,[i]:j}))} className="mt-0.5"/><span>{option}</span></label>)}</div>{checked&&<p className="mt-3 rounded-xl bg-slate-50 p-3 text-sm leading-5 text-slate-700">{answers[i]===q.correct?"Верно. ":"Правильный ответ: "+q.options[q.correct]+". "}{q.why}</p>}</article>)}{!checked?<button onClick={()=>setChecked(true)} className="rounded-xl bg-indigo-600 px-5 py-3 font-bold text-white hover:bg-indigo-700">Проверить ответы</button>:<div className="card p-5"><div className="text-xl font-black">Результат: {score} из {quiz.length}</div><p className="mt-1 text-sm text-slate-600">Разбери пояснения к ошибкам и пройди тест ещё раз.</p><button onClick={()=>{setAnswers({});setChecked(false);}} className="mt-3 rounded-xl border px-4 py-2 text-sm font-bold">Пройти повторно</button></div>}</section>}

    {view==="tasks" && <section className="space-y-4">
      <div className="card p-4"><h2 className="font-bold text-slate-900">Ситуационные задачи</h2><p className="mt-1 text-sm text-slate-600">26 задач сгруппированы по темам. Сначала попробуй решить самостоятельно, затем открой разбор.</p><div className="mt-3 flex flex-wrap gap-2">{[{id:"all",title:"Все темы"},...topics].map(t=><button key={t.id} onClick={()=>setActiveTopic(t.id)} className={"rounded-lg border px-3 py-2 text-xs font-bold "+(activeTopic===t.id?"border-indigo-500 bg-indigo-50 text-indigo-700":"border-slate-200 text-slate-600")}>{t.title}</button>)}</div></div>
      {situationalTasks.filter(t=>activeTopic==="all"||t.topic===activeTopic).map(t=><article key={t.id} className="card overflow-hidden"><div className="p-4 sm:p-5"><div className="flex items-start gap-3"><span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-violet-50 text-sm font-extrabold text-violet-700">{t.id}</span><div><h3 className="font-bold text-slate-900">{t.title}</h3><p className="mt-1 text-xs text-slate-500">{topics.find(x=>x.id===t.topic)?.title}</p><p className="mt-3 text-sm leading-6 text-slate-700">{t.question}</p><details className="mt-3 rounded-xl border border-slate-200 bg-slate-50 p-3"><summary className="cursor-pointer text-sm font-bold text-indigo-700">Показать ответ и объяснение</summary><div className="mt-3"><div className="text-xs font-extrabold uppercase tracking-wide text-indigo-700">Ответ</div><p className="mt-1 text-sm leading-6 text-slate-700">{t.answer}</p><div className="mt-3 text-xs font-extrabold uppercase tracking-wide text-emerald-800">Простыми словами</div><p className="mt-1 text-sm leading-6 text-slate-700">{t.simple}</p></div></details></div></div></div></article>)}
    </section>}
    <p className="text-xs leading-5 text-slate-500">Примечание: формулировки и объяснения структурированы для подготовки по предоставленному материалу. Для спорных деталей ориентируйся на графики и терминологию преподавателя; в частности, фазы ПД и возбудимость ткани могут зависеть от принятой в пособии схемы.</p>
  </div>;
}
